// Studio registry selects formula-owned metadata; shared controls keep their identity.
let activeFormula=typeof STUDIO_FORMULAS==='undefined'?{id:'uber-bulb',groups:FORMULA_GROUPS,hidden:[],reference:REFERENCE_FORMULA_PARAMETERS,phases:referencePhases,upload:uploadFormulaUniforms}:STUDIO_FORMULAS[0];
function studioGroups(formula){
 const fg=Object.values(formula.groups).map(g=>JSON.parse(JSON.stringify(g)));
 const transform=fg.find(g=>g[0]==='旋转与位置');if(transform)transform[3].unshift([...CAMERA_ROLL_PARAMETER]);
 return [fg[0],...['材质','OSL 渐变混合','灯光'].map(copyRendererGroup),...fg.slice(1),copyRendererGroup('渲染稳定性')];
}
let groups=studioGroups(activeFormula);


/* source: src/ui/studio/parameter-controls.js */
const LOCKED_PHASES=new Set(['LoopPI','LoopPI2','Loop1Start','Loop1End','Loop2Start','Loop2End']);
const isMaterialColor=key=>key==='ColorA'||key==='ColorB'||['KeyColor','FillColor','RimColor'].includes(key);
const colorHex=n=>'#'+Math.round(n).toString(16).padStart(6,'0');
const colorLinear=n=>[n>>16&255,n>>8&255,n&255].map(x=>{const s=x/255;return s<=.04045?s/12.92:Math.pow((s+.055)/1.055,2.4);});
const schema=new Map(),defaults={},fields=new Map();
function renderParameterControls(){schema.clear();fields.clear();for(const key of Object.keys(defaults))delete defaults[key];$('parameter-groups').replaceChildren();for(const [name,hint,open,items] of groups){const section=document.createElement('details');section.className='param-group';section.open=open;const sum=document.createElement('summary');sum.title=hint;sum.innerHTML=name+'<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 6 4 4 4-4" stroke-width="1.3"/></svg>';const reset=document.createElement('button');reset.type='button';reset.className='group-reset';reset.textContent='reset';reset.setAttribute('aria-label','重置 '+name);reset.onclick=e=>{e.preventDefault();e.stopPropagation();resetParameterGroup(name);};sum.insertBefore(reset,sum.querySelector('svg'));section.append(sum);const info=document.createElement('p');info.className='group-hint';info.textContent=hint;section.append(info);for(const def of items){const [key,label,min,max,step,value]=def;schema.set(key,def);defaults[key]=typeof min==='string'?max:value;const field=document.createElement('div');let input,range;const lab=document.createElement('label');lab.textContent=label;lab.htmlFor='u-'+key;if(isMaterialColor(key)){field.className='field-color';input=document.createElement('input');input.type='color';const hex=document.createElement('input');hex.type='text';hex.id='hex-'+key;hex.maxLength=7;hex.setAttribute('aria-label',label+'色值');hex.placeholder='#RRGGBB';hex.oninput=()=>{const valid=/^#[0-9a-f]{6}$/i.test(hex.value);hex.setAttribute('aria-invalid',String(!valid));if(valid)change(key,parseInt(hex.value.slice(1),16));};field.append(lab,input,hex);}else if(min==='bool'){field.className='field-check';input=document.createElement('input');input.type='checkbox';field.append(lab,input);}else if(min==='select'){field.className='field-select';input=document.createElement('select');for(const [text,v] of step){const o=document.createElement('option');o.value=v;o.textContent=text;input.append(o);}field.append(lab,input);}else{field.className='field';const row=document.createElement('div');row.className='field-row';input=document.createElement('input');input.type='number';Object.assign(input,{min,max,step});row.append(lab,input);range=document.createElement('input');range.type='range';Object.assign(range,{min,max,step});range.setAttribute('aria-label',label);field.append(row,range);}input.id='u-'+key;input.addEventListener('input',()=>{if(input.type==='number'&&(input.value===''||input.validity.badInput))return;change(key,isMaterialColor(key)?parseInt(input.value.slice(1),16):min==='bool'?Number(input.checked):Number(input.value));});if(range)range.oninput=()=>change(key,Number(range.value));fields.set(key,{input,range});if(LOCKED_PHASES.has(key)){field.hidden=true;input.disabled=true;if(range)range.disabled=true;}section.append(field);}if(items.every(def=>LOCKED_PHASES.has(def[0])))section.hidden=true;$('parameter-groups').append(section);}

for(const def of activeFormula.hidden){schema.set(def[0],def);defaults[def[0]]=typeof def[2]==='string'?def[3]:def[5];}
reference={...defaults,...activeFormula.reference,...activeFormula.profile?.parameters};}
let reference={};renderParameterControls();


