const lightPanel=fields.get('KeyAzimuth').input.closest('details');
const lightWidget=document.createElement('div');lightWidget.className='light-direction';
lightWidget.innerHTML='<div><h3>主光方向</h3><p>拖动球体环绕光源 · 可转至背面</p><output id="light-angle"></output><button id="light-reset">恢复参考打光</button></div><canvas id="light-ball" width="180" height="180" tabindex="0" role="img" aria-label="主光方向球体，拖动或使用方向键调整360度入射角"></canvas>';
lightPanel.querySelector('.group-hint').after(lightWidget);
const lightBall=$('light-ball'),lightCtx=lightBall.getContext('2d');let lightDrag=null;
function drawLightBall(){if(!lightCtx)return;const az=values.KeyAzimuth*Math.PI/180,el=values.KeyElevation*Math.PI/180;const l=[Math.cos(el)*Math.sin(az),Math.sin(el),Math.cos(el)*Math.cos(az)];const image=lightCtx.createImageData(180,180);for(let y=0;y<180;y++)for(let x=0;x<180;x++){const nx=(x-90)/72,ny=(90-y)/72,r=nx*nx+ny*ny;if(r>1)continue;const nz=Math.sqrt(1-r),shade=Math.max(0,nx*l[0]+ny*l[1]+nz*l[2]),i=(y*180+x)*4;image.data[i]=20+shade*(values.KeyColor>>16&255)*.7;image.data[i+1]=20+shade*(values.KeyColor>>8&255)*.65;image.data[i+2]=20+shade*(values.KeyColor&255)*.6;image.data[i+3]=255;}lightCtx.putImageData(image,0,0);lightCtx.strokeStyle='#777777';lightCtx.lineWidth=1;lightCtx.beginPath();lightCtx.arc(90,90,72,0,TAU);lightCtx.stroke();lightCtx.strokeStyle='#aaaaaa';lightCtx.globalAlpha=.4;lightCtx.beginPath();lightCtx.ellipse(90,90,72,20,0,0,TAU);lightCtx.stroke();lightCtx.globalAlpha=1;lightCtx.setLineDash(l[2]<0?[3,3]:[]);const accent=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()||'#b1ff49';lightCtx.strokeStyle=accent;lightCtx.fillStyle=accent;lightCtx.lineWidth=2;lightCtx.beginPath();lightCtx.arc(90+l[0]*72,90-l[1]*72,6,0,TAU);if(l[2]>=0)lightCtx.fill();else lightCtx.stroke();lightCtx.setLineDash([]);$('light-angle').textContent='方位 '+values.KeyAzimuth.toFixed(1)+'°\n仰角 '+values.KeyElevation.toFixed(1)+'° · '+(l[2]>=0?'前侧':'背侧');}
function setLightDirection(az,el){const a=az*Math.PI/180,e=el*Math.PI/180;values.KeyAzimuth=Math.round(Math.atan2(Math.cos(e)*Math.sin(a),Math.cos(e)*Math.cos(a))*180/Math.PI*1000)/1000;values.KeyElevation=Math.round(Math.asin(Math.max(-1,Math.min(1,Math.sin(e))))*180/Math.PI*1000)/1000;referencePreset=false;sync();dirty=true;}
lightBall.onpointerdown=e=>{cancelPresetTransition();lightBall.focus({preventScroll:true});lightBall.setPointerCapture(e.pointerId);lightDrag={id:e.pointerId,x:e.clientX,y:e.clientY,az:values.KeyAzimuth,el:values.KeyElevation};};
lightBall.onpointermove=e=>{if(!lightDrag||e.pointerId!==lightDrag.id)return;setLightDirection(lightDrag.az+(e.clientX-lightDrag.x)*1.5,lightDrag.el-(e.clientY-lightDrag.y)*1.5);};
for(const event of ['pointerup','pointercancel','lostpointercapture'])lightBall.addEventListener(event,()=>lightDrag=null);
lightBall.onkeydown=e=>{cancelPresetTransition();const step=e.shiftKey?15:5;if(!e.key.startsWith('Arrow'))return;e.preventDefault();setLightDirection(values.KeyAzimuth+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),values.KeyElevation+(e.key==='ArrowUp'?step:e.key==='ArrowDown'?-step:0));};
$('light-reset').onclick=()=>{cancelPresetTransition();values.KeyAzimuth=reference.KeyAzimuth;values.KeyElevation=reference.KeyElevation;sync();dirty=true;};




