document.addEventListener('fullscreenchange',()=>{const active=document.fullscreenElement===fullscreenStage,button=$('view-fullscreen'),label=active?'退出全屏':'全屏画面';button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',label);button.title=label;dirty=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.fullscreenElement===fullscreenStage)document.exitFullscreen().catch(()=>{});});


